  "composer.predictionModel": "\u041C\u043E\u0434\u0435\u043B\u044C \u043F\u0440\u0435\u0434\u0441\u043A\u0430\u0437\u0430\u043D\u0438\u044F",
  "composer.predictionModelHint": "\u041F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u0441\u043B\u0435\u0434\u0443\u0435\u0442 \u0437\u0430 \u0442\u0435\u043A\u0443\u0449\u0438\u043C \u0434\u0438\u0430\u043B\u043E\u0433\u043E\u043C; \u0438\u043B\u0438 \u0443\u043A\u0430\u0436\u0438\u0442\u0435 \u0431\u044B\u0441\u0442\u0440\u0443\u044E \u043C\u043E\u0434\u0435\u043B\u044C.",
