  "sections.new": "\u041D\u043E\u0432\u0430\u044F \u0441\u0435\u043A\u0446\u0438\u044F",
  "sections.newName": "\u041D\u0430\u0437\u0432\u0430\u043D\u0438\u0435 \u0441\u0435\u043A\u0446\u0438\u0438",
  "sections.pin": "\u0417\u0430\u043A\u0440\u0435\u043F\u0438\u0442\u044C",
